mapper.insert:
INSERT INTO RESERVATIONS (user_id, seat_id, round_id, performance_id, reserved_status, ins_id, ins_ip)
SELECT NULL, s.seat_id, #{roundId}, #{performanceId}, 'AVAILABLE', #{insId}, #{insIp}
FROM SEATS s
JOIN PERFORMANCES p ON s.venue_id = p.venue_id
WHERE p.performance_id = #{performanceId}

mapper.select:
SELECT COUNT(*) FROM PERFORMANCES P LEFT OUTER JOIN VENUE V ON P.venue_id = V.venue_id
AND P.category_id = #{categoryId}
AND (P.p_title LIKE CONCAT('%', #{keyword}, '%') OR V.venue_name LIKE CONCAT('%', #{keyword}, '%'))

mapper.update:
UPDATE PERFORMANCES
p_title = #{pTitle}, poster_url = #{posterUrl}, category_id = #{categoryId}, upt_id = #{uptId}, upt_ip = #{uptIp},
WHERE performance_id = #{performanceId}

UPDATE PERFORMANCE_ROUND
SET round_time = #{roundTime}, open_time = #{openTime}, upt_id = #{uptId}, upt_ip = #{uptIp}
WHERE round_id = #{roundId}
